INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(130219, 'ruRU', '', 'Мои стрелы бьют точно!', 24330),
(130232, 'ruRU', '', 'Прежде чем меня изгнали, я была смотрителем аквариума в городе. Жизнь, что существует в том резервуаре, всё ещё моя ответственность, и я не оставлю их!', 24330),
(130233, 'ruRU', '', 'Великолепно! Вот, просто положи их в мою заколдованную сферу воды, а об остальном позабочусь я.\n\n<Ша\'лет, кажется, отвлеклась, наблюдая за крошечными рыбками.>', 24330),
(130234, 'ruRU', '', 'Ох! Первым делом, карпы кои в аквариуме начинают теснить друг друга. Может, если ты поймаешь немного мальков, я смогу выпустить их в реки?\n\nБереги Магикус, стража аквариума.', 24330),
(130235, 'ruRU', '', 'Порча душит наши воды и убивает естественную жизнь, что некогда процветала там. Мы должны дать отпор!', 24330),
(130236, 'ruRU', '', '<Она протягивает руку и забирает капли, отвернув голову с отвращением.>\n\nБлагодарю. Мне доставит удовольствие уничтожить это.', 24330),
(130237, 'ruRU', '', 'Без сомнения, ты уже сражаешься с чудовищами, вторгшимися в наш лес. Но если бы мы могли извлечь более... вязкую... порчу из самой воды, это тоже было бы большой победой! Советую попробовать удочку.', 24330),
(130242, 'ruRU', '', 'Помогите! Они пытаются добраться до моих припасов!', 24330),
(130243, 'ruRU', '', 'Огромное спасибо! Пожалуйста, возьми этот сундук из тайника. Ты это заслужил!', 24330),
(130311, 'ruRU', '', 'Хммм....? Хммм.', 24330),
(130312, 'ruRU', '', 'Ох, ты милый, но я уже связана контрактом.', 24330),
(130314, 'ruRU', '', 'Ох, какие восхитительные принципы у тебя.', 24330),
(130316, 'ruRU', '', 'Ооо... мне так холодно. Будь добр, подожги себя ради меня?', 24330),
(130319, 'ruRU', '', '<Просто много подмигивает.>', 24330),
(130332, 'ruRU', '', 'Ооо, писарь? Как я люблю, когда кто-то записывает мои маленькие... доминирования. Возможно, я знаю один маленький секрет. Тёмный секрет.\n\nТы из тех, кто целует и рассказывает? Потому что я - да.', 24330),
(130337, 'ruRU', '', 'Мм... как я люблю хорошего писаря. Обязательно оставайся... на связи.', 24330),
(130414, 'ruRU', '', 'Добро пожаловать на Испытание стиля: лучшее модное направление Азерота!', 24330),
(130417, 'ruRU', '', 'Тема сегодняшнего соревнования... Летние стили!', 24330),
(130419, 'ruRU', '', 'Потрать следующие несколько моментов, чтобы подготовить свой костюм.', 24330),
(130420, 'ruRU', '', 'Мы также предоставили парикмахерские кресла, если тебе нужно подправить причёску.', 24330),
(130422, 'ruRU', '', '$ct, алхимики Фелскорна в этой области становятся всё агрессивнее последнее время. Недавно они украли партию нашего пива. Хуже того, похоже, они изменили его, чтобы усилить себя, и теперь разбрызгивают его из своих распылителей!\n\nИх нужно остановить, но без помощи это будет непросто. К счастью, Царь Обезьян одолжил нам свой прыжковый посох. Используй его, чтобы перескакивать через их головы и обрушивать смерть сверху!\n\nПоможешь?', 24330),
(130425, 'ruRU', '', 'Пылающий Легион приближается к Азероту. Мы все должны делать свою часть работы!', 24330),
(130431, 'ruRU', '', 'Слева от вас - потрясающий $n!', 24330),
(130435, 'ruRU', '', 'Третье место занимает... $n! Поздравляем, $n!', 24330),
(130437, 'ruRU', '', 'И наконец, наш великий чемпион трансмогрификации этого вечера. Поприветствуем $n!', 24330),
(130438, 'ruRU', '', 'Все остальные, продолжайте пытаться. Скоро вы станете чемпионами.', 24330),
(130439, 'ruRU', '', 'Это всё на сегодня. До следующего раза!', 24330),
(130447, 'ruRU', '', 'Оро Младший, оставайся там! Твой отец был бы безутешен, если бы с тобой что-то случилось.', 24330),
(130452, 'ruRU', '', 'Тема сегодняшнего соревнования... Зимняя одежда!', 24330),
(130453, 'ruRU', '', 'Тема сегодняшнего соревнования... Готовность к битве!', 24330),
(130454, 'ruRU', '', 'Тема сегодняшнего соревнования... Весело и игриво!', 24330),
(130455, 'ruRU', '', 'Тема сегодняшнего соревнования... Безумное несоответствие!', 24330),
(130456, 'ruRU', '', 'Тема сегодняшнего соревнования... Огонь и лёд!', 24330),
(130457, 'ruRU', '', 'Тема сегодняшнего соревнования... Тёмное и смертоносное!', 24330),
(130458, 'ruRU', '', 'Тема сегодняшнего соревнования... Гордость фракции!', 24330),
(130459, 'ruRU', '', 'Тема сегодняшнего соревнования... Первобытный стиль!', 24330),
(130460, 'ruRU', '', 'Тема сегодняшнего соревнования... Герои Азерота!', 24330),
(130461, 'ruRU', '', 'Тема сегодняшнего соревнования... Рассмеши меня!', 24330),
(130462, 'ruRU', '', 'Тема сегодняшнего соревнования... Время накидок!', 24330),
(130463, 'ruRU', '', 'Тема сегодняшнего соревнования... Герои на каждый день!', 24330);
